
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_hcth_a_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_hcth_a", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.456890735951493e+00, -4.364750419970397e+00, -4.235776953454931e+00, -4.057420018556937e+00, -3.815074192930921e+00, -3.494146862801793e+00, -3.085037353089124e+00, -2.592809542915959e+00, -2.052280254526155e+00, -1.535701925908281e+00, -1.072630039391101e+00, -7.289505774354120e-01, -6.348662410867136e-01, -5.036952054775077e-01, -3.574603260860368e-01, -2.473620828186768e-01, -1.995718536082459e-01, -1.775115964849115e-01, -1.411692572009224e-01, -1.036014454199669e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


